    if (tab === 'search' && !(opts && opts.noFocus)) searchEl.focus();
    // تحديث صامت لبيانات VIP عند العودة للصفحة الرئيسية
    if (tab === 'home' || tab === 'vip' || tab === 'account') refreshMe();
